con:mockOperation.con:dispatchPath:
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import groovy.xml.XmlSlurper
import java.time.Instant

try {
    // 1. Lectura del XML entrante
    def requestXml = new XmlSlurper().parseText(mockRequest.requestContent)
    def texto = requestXml.Body.buscar.texto.text()?.trim()?.toLowerCase() ?: ""
    def categoria = requestXml.Body.buscar.categoria.text()?.trim()?.toLowerCase() ?: ""

    // 2. Ruta dinámica de archivos
    def projectPath = mockOperation.mockService.project.path
    def baseDir = projectPath ? new File(projectPath).parentFile : new File(".")
    def datosFile = new File(baseDir, "datos.json")
    def consultasFile = new File(baseDir, "consultas.json")

    // 3. Cargar datos de prueba respaldados
    def baseDatos = []
    if (datosFile.exists() && datosFile.length() > 0) {
        try {
            baseDatos = new JsonSlurper().parse(datosFile)
        } catch (Exception e) {
            baseDatos = []
        }
    }

    // Si datos.json no existe o está vacío, usar datos por defecto
    if (baseDatos.isEmpty()) {
        baseDatos = [
            [titulo: "Introducción a Software Architecture", descripcion: "Conceptos de arquitectura REST y SOAP", categoria: "Ingeniería", fechaPublicacion: "2026-01-15"],
            [titulo: "Desarrollo con Kotlin y Room", descripcion: "Bases de datos locales en Android Studio", categoria: "Móvil", fechaPublicacion: "2026-03-10"],
            [titulo: "Configuración de Servicios Web PHP", descripcion: "Consumo de API SOAP con SoapClient", categoria: "Ingeniería", fechaPublicacion: "2026-05-20"]
        ]
    }

    // 4. Filtrar resultados
    def resultadosFiltrados = baseDatos.findAll { item ->
        def coincideTexto = texto ? (item.titulo?.toLowerCase()?.contains(texto) || item.descripcion?.toLowerCase()?.contains(texto)) : true
        def coincideCat = categoria ? (item.categoria?.toLowerCase()?.contains(categoria)) : true
        return coincideTexto && coincideCat
    }

    // 5. Intentar guardar en consultas.json de forma segura
    try {
        def consultas = (consultasFile.exists() && consultasFile.length() > 0) ? new JsonSlurper().parse(consultasFile) : []
        def nuevaConsulta = [
            id: "CONS-" + System.currentTimeMillis(),
            texto: texto,
            categoria: categoria,
            cantidadResultados: resultadosFiltrados.size(),
            creadaEn: Instant.now().toString(),
            expiraEn: Instant.now().plusSeconds(86400).toString()
        ]
        consultas.add(nuevaConsulta)
        consultasFile.write(JsonOutput.toJson(consultas))
    } catch (Exception e) {
        // Si no se puede escribir el historial, el flujo continúa sin romper la búsqueda
    }

    // 6. Generar XML de resultados
    StringBuilder resultadosXml = new StringBuilder()
    resultadosFiltrados.each { item ->
        resultadosXml.append("""
            <bus:resultado>
                <bus:titulo>${item.titulo ?: ''}</bus:titulo>
                <bus:descripcion>${item.descripcion ?: ''}</bus:descripcion>
                <bus:categoria>${item.categoria ?: ''}</bus:categoria>
                <bus:fechaPublicacion>${item.fechaPublicacion ?: ''}</bus:fechaPublicacion>
            </bus:resultado>
        """)
    }

    // 7. Definir respuesta SOAP
    requestContext.responseXml = """<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:bus="http://motorbusqueda/">
       <soapenv:Header/>
       <soapenv:Body>
          <bus:buscarResponse>
             <bus:consultaId>CONS-${System.currentTimeMillis()}</bus:consultaId>
             <bus:cantidad>${resultadosFiltrados.size()}</bus:cantidad>
             <bus:resultados>
                ${resultadosXml.toString()}
             </bus:resultados>
          </bus:buscarResponse>
       </soapenv:Body>
    </soapenv:Envelope>"""

} catch (Exception e) {
    // Retorno de Fault ante cualquier fallo de ejecución
    requestContext.responseXml = """<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/">
       <soapenv:Body>
          <soapenv:Fault>
             <faultcode>SOAP-ENV:Server</faultcode>
             <faultstring>Error en Groovy buscar: ${e.message.replaceAll('<', '&lt;')}</faultstring>
          </soapenv:Fault>
       </soapenv:Body>
    </soapenv:Envelope>"""
}

// Asegúrate de que este nombre sea exactamente igual al nombre de tu respuesta en la operación
return "RespuestaBusqueda"

import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import groovy.xml.XmlSlurper
import java.time.Instant

try {
    // 1. Obtener directorio base del proyecto de forma dinámica
    def projectFile = new File(mockOperation.mockService.project.path)
    def baseDir = projectFile.parentFile ?: new File(".")
    def queryFile = new File(baseDir, "consultas.json")

    // 2. Parsear el XML de la petición de forma segura
    def requestXml = new XmlSlurper().parseText(mockRequest.requestContent)
    def rol = requestXml.Body.obtenerDashboard.rol.text()?.trim() ?: "CLIENTE"

    int totalActivas = 0
    String terminoMasBuscado = "N/A"
    String categoriaMasBuscada = "N/A"
    StringBuilder consultasXml = new StringBuilder()

    // 3. Procesar consultas si el archivo existe
    if (queryFile.exists() && queryFile.length() > 0) {
        def jsonSlurper = new JsonSlurper()
        def consultas = jsonSlurper.parse(queryFile)
        def now = Instant.now()

        // Filtrar consultas activas
        def activas = consultas.findAll { item ->
            try {
                return Instant.parse(item.expiraEn).isAfter(now)
            } catch (Exception e) {
                return false
            }
        }

        totalActivas = activas.size()

        if (!activas.isEmpty()) {
            // Calcular término más buscado
            def terminos = activas.collect { it.texto?.toLowerCase() }.findAll { it }
            if (terminos) {
                terminoMasBuscado = terminos.groupBy { it }.max { it.value.size() }?.key ?: "N/A"
            }

            // Calcular categoría más buscada
            def categorias = activas.collect { it.categoria?.toLowerCase() }.findAll { it }
            if (categorias) {
                categoriaMasBuscada = categorias.groupBy { it }.max { it.value.size() }?.key ?: "N/A"
            }

            // Generar XML de consultas recientes (últimas 5)
            activas.take(5).each { item ->
                consultasXml.append("""
                    <bus:consulta>
                        <bus:id>${item.id}</bus:id>
                        <bus:texto>${item.texto ?: ''}</bus:texto>
                        <bus:categoria>${item.categoria ?: ''}</bus:categoria>
                        <bus:cantidadResultados>${item.cantidadResultados ?: 0}</bus:cantidadResultados>
                        <bus:creadaEn>${item.creadaEn ?: ''}</bus:creadaEn>
                    </bus:consulta>
                """)
            }
        }
    }

    // 4. Construir respuesta SOAP exitosa
    requestContext.responseXml = """<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:bus="http://motorbusqueda/">
       <soapenv:Header/>
       <soapenv:Body>
          <bus:obtenerDashboardResponse>
             <bus:totalConsultasActivas>${totalActivas}</bus:totalConsultasActivas>
             <bus:terminoMasBuscado>${terminoMasBuscado}</bus:terminoMasBuscado>
             <bus:categoriaMasBuscada>${categoriaMasBuscada}</bus:categoriaMasBuscada>
             <bus:consultasRecientes>
                ${consultasXml.toString()}
             </bus:consultasRecientes>
          </bus:obtenerDashboardResponse>
       </soapenv:Body>
    </soapenv:Envelope>"""

} catch (Exception e) {
    // Si hay algún error, devuelve un SOAP Fault explicativo en lugar de dar Error 500
    requestContext.responseXml = """<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/">
       <soapenv:Body>
          <soapenv:Fault>
             <faultcode>SOAP-ENV:Server</faultcode>
             <faultstring>Error interno en Groovy: ${e.message.replaceAll('<', '&lt;')}</faultstring>
          </soapenv:Fault>
       </soapenv:Body>
    </soapenv:Envelope>"""
}

return "Response 1"
